CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE EXTENSION IF NOT EXISTS postgis;
CREATE TABLE IF NOT EXISTS organizations (id uuid PRIMARY KEY, name text NOT NULL, kind text NOT NULL CHECK (kind IN ('BRANCH','AREA','REGION')));
CREATE TABLE IF NOT EXISTS users (id uuid PRIMARY KEY, username text UNIQUE NOT NULL, role text NOT NULL CHECK (role IN ('CDO','CO','BM','AM','RM','ADMIN')), department text NOT NULL CHECK (department IN ('DABI','PROGOTI','SHARED')), branch_id uuid REFERENCES organizations(id), area_id uuid REFERENCES organizations(id), region_id uuid REFERENCES organizations(id), active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS customers (id uuid PRIMARY KEY, customer_ref text UNIQUE NOT NULL, display_name text NOT NULL, branch_id uuid NOT NULL REFERENCES organizations(id), area_id uuid NOT NULL REFERENCES organizations(id), region_id uuid NOT NULL REFERENCES organizations(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS applications (id uuid PRIMARY KEY, product text NOT NULL CHECK (product IN ('DABI','PROGOTI')), customer_id uuid NOT NULL REFERENCES customers(id), status text NOT NULL, version integer NOT NULL DEFAULT 1, owner_id uuid NOT NULL REFERENCES users(id), branch_id uuid NOT NULL REFERENCES organizations(id), area_id uuid NOT NULL REFERENCES organizations(id), region_id uuid NOT NULL REFERENCES organizations(id), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS application_versions (id uuid PRIMARY KEY, application_id uuid NOT NULL REFERENCES applications(id), version integer NOT NULL, payload jsonb NOT NULL DEFAULT '{}'::jsonb, frozen boolean NOT NULL DEFAULT false, created_by uuid NOT NULL REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(application_id, version));
CREATE TABLE IF NOT EXISTS workflow_actions (id uuid PRIMARY KEY, application_id uuid NOT NULL REFERENCES applications(id), application_version integer NOT NULL, actor_id uuid NOT NULL REFERENCES users(id), actor_role text NOT NULL, action text NOT NULL, from_status text NOT NULL, to_status text NOT NULL, remarks text, idempotency_key text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(actor_id, idempotency_key));
CREATE TABLE IF NOT EXISTS idempotency_keys (key text PRIMARY KEY, actor_id uuid NOT NULL REFERENCES users(id), request_hash text NOT NULL, response jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS applications_scope_idx ON applications(branch_id, area_id, region_id, status);
CREATE INDEX IF NOT EXISTS workflow_actions_app_idx ON workflow_actions(application_id, created_at);
